import{_ as d,o as e,c as r,a0 as a}from"./chunks/framework.DYAX5gPL.js";const s=JSON.parse('{"title":"矢量数据图层的性能优化","description":"","frontmatter":{"title":"矢量数据图层的性能优化"},"headers":[],"relativePath":"api/vt-performance.md","filePath":"api/vt-performance.md"}'),l={name:"api/vt-performance.md"};function o(i,t,n,p,c,h){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="矢量数据图层的性能优化" tabindex="-1">矢量数据图层的性能优化 <a class="header-anchor" href="#矢量数据图层的性能优化" aria-label="Permalink to &quot;矢量数据图层的性能优化&quot;">​</a></h1><p>这里的矢量数据图层包括矢量瓦片图层<a href="/api/vector-tile-layer.html">VectorTileLayer</a>和矢量图层（<a href="/api/point-layer.html">PointLayer</a>，<a href="/api/line-string-layer.html">LineStringLayer</a>和<a href="/api/polygon-layer.html">PolygonLayer</a>）。</p><h2 id="样式更新的性能" tabindex="-1">样式更新的性能 <a class="header-anchor" href="#样式更新的性能" aria-label="Permalink to &quot;样式更新的性能&quot;">​</a></h2><p>基于Web 3D技术实现的矢量图层是将图形数据构造为一个通常称为Mesh的三维数据结构，然后交给Web 3D接口绘制的。</p><p>样式更新对性能的影响主要在于Mesh的更新是局部更新还是整体更新。</p><ul><li>局部更新指只更新Mesh中的更新了的数据，不需要重新构造</li><li>整体更新指Mesh需要整体的重新构造</li></ul><p>因此如果应用场景需要优化性能，需要尽量避免Mesh的整体更新，以下列出会造成Mesh整体更新的symbol属性，性能敏感的场景下，请避免频繁更新它们，其他没有列出的Symbol属性均不会造成Mesh整体更新。</p><blockquote><p>❗ 表示会造成Mesh整体更新，🆗则表示不会</p></blockquote><table tabindex="0"><thead><tr><th>属性名</th><th>矢量瓦片图层</th><th>矢量图层</th></tr></thead><tbody><tr><td>markerFile</td><td>❗</td><td>❗</td></tr><tr><td>markerPlacement</td><td>❗</td><td>❗</td></tr><tr><td>markerSpacing</td><td>❗</td><td>❗</td></tr><tr><td>markerHorizontalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>markerVerticalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textName</td><td>❗</td><td>❗</td></tr><tr><td>textFaceName</td><td>❗</td><td>❗</td></tr><tr><td>textPlacement</td><td>❗</td><td>❗</td></tr><tr><td>textSpacing</td><td>❗</td><td>❗</td></tr><tr><td>textHorizontalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textVerticalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textWrapWidth</td><td>❗</td><td>🆗</td></tr><tr><td>lineJoin</td><td>❗</td><td>❗</td></tr><tr><td>lineCap</td><td>❗</td><td>❗</td></tr><tr><td>linePatternFile</td><td>❗</td><td>❗</td></tr><tr><td>lineDasharray</td><td>🆗</td><td>❗</td></tr><tr><td>polygonPatternFile</td><td>❗</td><td>❗</td></tr><tr><td>topPolygonFill</td><td>🆗</td><td>❗</td></tr><tr><td>bottomPolygonFill</td><td>🆗</td><td>❗</td></tr></tbody></table><blockquote><p>注：旧文档中的 <code>textStyle</code>、<code>textWeight</code> 两个属性已在 @maptalks/gl-layers 新版本中移除（2026 源码中已注释），不再触发Mesh重建；<code>topPolygonFill</code>、<code>bottomPolygonFill</code> 为 3D 拉伸面图层（ExtrudePolygonLayer）新增的属性（2026 核对）。</p></blockquote><blockquote><p>本文档已与 @maptalks/gl-layers 2026 源码核对（api-notes-vt-gl.md）</p></blockquote>',11)])])}const y=d(l,[["render",o]]);export{s as __pageData,y as default};
